$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'experiment-1-22-native-log-capture.ps1');. (Join-Path $PSScriptRoot 'experiment-1-22-container-stop.ps1');$root=Join-Path $env:TEMP ('exp122-capture-fixtures-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory -Force $root;$name=$null
